class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], diff: int) -> int:
        a = [x - y for x, y in zip(nums1, nums2)]
        self.ans = 0
        def ms(lo, hi):
            if hi - lo <= 1:
                return
            m = (lo + hi) // 2
            ms(lo, m)
            ms(m, hi)
            j = m
            for i in range(lo, m):
                while j < hi and a[j] < a[i] - diff:
                    j += 1
                self.ans += hi - j
            a[lo:hi] = sorted(a[lo:hi])
        ms(0, len(a))
        return self.ans

