class Solution {
public:
    long long ans = 0;
    int diff;
    void ms(vector<int>& a, int lo, int hi) {
        if (hi - lo <= 1) return;
        int m = (lo + hi) / 2;
        ms(a, lo, m); ms(a, m, hi);
        int j = m;
        for (int i = lo; i < m; i++) {
            while (j < hi && a[j] < a[i] - diff) j++;
            ans += hi - j;
        }
        inplace_merge(a.begin() + lo, a.begin() + m, a.begin() + hi);
    }
    long long numberOfPairs(vector<int>& nums1, vector<int>& nums2, int d) {
        diff = d;
        int n = nums1.size();
        vector<int> a(n);
        for (int i = 0; i < n; i++) a[i] = nums1[i] - nums2[i];
        ms(a, 0, n);
        return ans;
    }
};

