            ans += hi - j;
        }
        long[] t = Arrays.copyOfRange(a, lo, hi);
        Arrays.sort(t);
        System.arraycopy(t, 0, a, lo, hi - lo);
    }
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        this.diff = diff;
        int n = nums1.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nums1[i] - nums2[i];
        ms(a, 0, n);
        return ans;
    }
}

