    let ans = 0;
    function ms(lo, hi) {
        if (hi - lo <= 1) return;
        const m = (lo + hi) >> 1;
        ms(lo, m); ms(m, hi);
        let j = m;
        for (let i = lo; i < m; i++) {
            while (j < hi && a[j] < a[i] - diff) j++;
