class Solution {
public:
    vector<int> tr;
    void upd(int i, int m) { for (i++; i <= m; i += i & -i) tr[i]++; }
    long long qry(int i) { long long s = 0; for (; i > 0; i -= i & -i) s += tr[i]; return s; }
    long long numberOfPairs(vector<int>& nums1, vector<int>& nums2, int diff) {
        int n = nums1.size();
        vector<int> a(n);
        for (int i = 0; i < n; i++) a[i] = nums1[i] - nums2[i];
        vector<int> sv = a;
        sort(sv.begin(), sv.end());
        sv.erase(unique(sv.begin(), sv.end()), sv.end());
        int m = sv.size();
        tr.assign(m + 1, 0);
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int lo = lower_bound(sv.begin(), sv.end(), a[i] - diff) - sv.begin();
            ans += i - qry(lo);
            upd(lower_bound(sv.begin(), sv.end(), a[i]) - sv.begin(), m);
        }
        return ans;
    }
};

