class Solution {
    int[] tr;
    void upd(int i, int m) { for (i++; i <= m; i += i & -i) tr[i]++; }
    long qry(int i) { long s = 0; for (; i > 0; i -= i & -i) s += tr[i]; return s; }
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nums1[i] - nums2[i];
        TreeSet<Long> set = new TreeSet<>();
        for (long x : a) set.add(x);
        List<Long> sv = new ArrayList<>(set);
        int m = sv.size();
        tr = new int[m + 1];
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int lo = Collections.binarySearch(sv, a[i] - diff);
            lo = lo < 0 ? -(lo + 1) : lo;
            ans += i - qry(lo);
            int id = Collections.binarySearch(sv, a[i]);
            upd(id, m);
        }
        return ans;
    }
}

