var numberOfPairs = function(nums1, nums2, diff) {
    const a = nums1.map((x, i) => x - nums2[i]);
    const sv = [...new Set(a)].sort((x, y) => x - y);
    const m = sv.length;
    const tr = Array(m + 1).fill(0);
    const id = x => { let lo = 0, hi = m; while (lo < hi) { const md = (lo + hi) >> 1; sv[md] < x ? lo = md + 1 : hi = md; } return lo; };
    const upd = i => { for (i++; i <= m; i += i & -i) tr[i]++; };
    const qry = i => { let s = 0; for (; i > 0; i -= i & -i) s += tr[i]; return s; };
    let ans = 0;
    for (let i = 0; i < a.length; i++) {
        ans += i - qry(id(a[i] - diff));
        upd(id(a[i]));
    }
    return ans;
};
